716:     try { [void][IO.Directory]::CreateDirectory($taskDir) } catch { Stop-WithError "could not create the task directory '$taskDir' ($(ConvertTo-OneLine $_.Exception.Message)); nothing was started." }
717:     $newId = ''
718:     $paths = $null
719:     foreach ($cand in $tries) {
720:         $p = Get-DetachedPaths -TaskDir $taskDir -Id $cand
721:         if ((Test-Path -LiteralPath $p.Status) -or (Test-Path -LiteralPath $p.Log)) { continue }
