789: # The -Status report of detached runs (newest first): per run its state, one line per member and,
790: # when it is done, the summary block the run printed - verbatim.
791: function Write-DetachedReport {
792:     param([object[]]$Runs, [DateTimeOffset]$Now = [DateTimeOffset]::Now)
793:     $first = $true
794:     foreach ($run in @($Runs)) {
795:         if (-not $first) { Write-Host '' }
796:         $first = $false
797:         $j = Get-DetachedJudgement -Record $run.Record -Problem ([string]$run.Error) -Now $Now
798:         $rec = $run.Record
799:         if (-not $rec) { Write-Host "detached $($run.Id8): $($j.Text)"; continue }
800:         $what = $(if ($rec.kind -eq 'panel') { 'review panel' } else { 'single run' })
801:         if ($rec.purpose) { $what += ", purpose $($rec.purpose)" }
802:         if ($rec.reply_name) { $what += ", reply name $($rec.reply_name)" }
803:         Write-Host "detached $($run.Id8) ($what): $($j.Text)"
