7008: # A timestamp field back as text ($null for none): a [datetime] or [DateTimeOffset] that
7009: # ConvertFrom-Json made of it (PowerShell 7) returns to the bridge's own form - the local ISO
7010: # form of Get-IsoTimestamp, or (-RoundTrip) the UTC round trip of Get-ProcessStartIso.
7011: function ConvertTo-DetachedTime {
7012:     param($Value, [switch]$RoundTrip)
7013:     if ($null -eq $Value -or ($Value -is [string] -and -not $Value)) { return $null }
7014:     if ($RoundTrip) { return (ConvertTo-JsonText $Value) }
7015:     $at = ConvertTo-WhenOffset $Value
7016:     if ($null -eq $at) { return [string]$Value }
7017:     return $at.ToString('yyyy-MM-ddTHH:mm:sszzz', $script:Invariant)
7018: }
