7020: # The record in its canonical form (every field, in order, timestamps as text) from a parsed
7021: # status file or a hashtable of fields: a record read and written back keeps its form under
7022: # PowerShell 7 too.
7023: function ConvertTo-DetachedRecord {
7024:     param($Record)
7025:     if ($Record -is [System.Collections.IDictionary]) { $Record = [pscustomobject]$Record }
7026:     $members = New-Object System.Collections.Generic.List[object]
7027:     foreach ($m in @(Get-PropertyValue $Record 'members' @())) {
7028:         if ($null -eq $m) { continue }
7029:         $nValue = $null
7030:         $nParsed = 0
7031:         if ([int]::TryParse([string](Get-PropertyValue $m 'n' ''), [ref]$nParsed)) { $nValue = $nParsed }
7032:         $members.Add((New-DetachedMember -Position ([int](Get-PropertyValue $m 'position' 0)) -Lineage ([string](Get-PropertyValue $m 'lineage' '')) -State ([string](Get-PropertyValue $m 'state' 'pending')) -Outcome ([string](Get-PropertyValue $m 'outcome' '')) -Wall (Get-PropertyValue $m 'wall_seconds' $null) -N $nValue -Handoff ([string](Get-PropertyValue $m 'handoff' '')) -Reply ([string](Get-PropertyValue $m 'reply' ''))))
7033:     }
7034:     $pidValue = $null
7035:     $parsed = 0
7036:     if ([int]::TryParse([string](Get-PropertyValue $Record 'pid' ''), [ref]$parsed) -and $parsed -gt 0) { $pidValue = $parsed }
7037:     $exitValue = $null
7038:     if ([int]::TryParse([string](Get-PropertyValue $Record 'exit' ''), [ref]$parsed)) { $exitValue = $parsed }
7039:     $budget = 0
7040:     [void][int]::TryParse([string](Get-PropertyValue $Record 'budget_sec' ''), [ref]$budget)
7041:     $version = $script:DetachedStatusVersion
7042:     if ([int]::TryParse([string](Get-PropertyValue $Record 'status_version' ''), [ref]$parsed)) { $version = $parsed }
7043:     return [pscustomobject]@{
7044:         status_version = $version
7045:         id             = [string](Get-PropertyValue $Record 'id' '')
7046:         id8            = [string](Get-PropertyValue $Record 'id8' '')
7047:         task           = [string](Get-PropertyValue $Record 'task' '')
7048:         kind           = [string](Get-PropertyValue $Record 'kind' 'run')
7049:         state          = [string](Get-PropertyValue $Record 'state' '')
7050:         exit           = $exitValue
7051:         started        = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'started' $null))
7052:         updated        = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'updated' $null))
7053:         finished       = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'finished' $null))
7054:         wall_seconds   = (Get-PropertyValue $Record 'wall_seconds' $null)
7055:         pid            = $pidValue
7056:         start_time     = (ConvertTo-DetachedTime (Get-PropertyValue $Record 'start_time' $null) -RoundTrip)
7057:         host           = [string](Get-PropertyValue $Record 'host' '')
7058:         budget_sec     = $budget
7059:         purpose        = [string](Get-PropertyValue $Record 'purpose' '')
7060:         reply_name     = [string](Get-PropertyValue $Record 'reply_name' '')
7061:         brief          = [string](Get-PropertyValue $Record 'brief' '')
7062:         members        = [object[]]$members.ToArray()
7063:         summary        = [string](Get-PropertyValue $Record 'summary' '')
7064:         log            = [string](Get-PropertyValue $Record 'log' '')
7065:         args           = $(if ([string](Get-PropertyValue $Record 'args' '')) { [string]$Record.args } else { $null })
7066:     }
