7069: # { Exists; Record (canonical); Error }. Absent -> Exists $false. Present but empty,
7070: # unparseable, not an object, without an id or with a state other than starting | running |
7071: # done -> Error.
7072: function Read-DetachedStatus {
7073:     param([string]$Path)
7074:     if (-not (Test-Path -LiteralPath $Path -PathType Leaf)) { return [pscustomobject]@{ Exists = $false; Record = $null; Error = '' } }
7075:     $text = Read-SharedText -Path $Path
7076:     $obj = $null
7077:     $why = ''
7078:     if (-not $text.Trim()) { $why = 'it is empty or could not be read' }
7079:     else {
7080:         try { $obj = ConvertFrom-Json -InputObject $text } catch { $why = "it does not parse: $(ConvertTo-OneLine $_.Exception.Message)" }
7081:         if (-not $why -and -not (Test-IsJsonObject $obj)) { $why = 'it is not a JSON object' }
7082:         if (-not $why -and -not [string](Get-PropertyValue $obj 'id' '')) { $why = 'it names no id' }
7083:         if (-not $why -and @('starting', 'running', 'done') -notcontains [string](Get-PropertyValue $obj 'state' '')) { $why = "its state '$(Get-PropertyValue $obj 'state' '')' is not one of starting|running|done" }
7084:     }
7085:     if ($why) { return [pscustomobject]@{ Exists = $true; Record = $null; Error = "the status file '$Path' cannot be used: $why" } }
7086:     return [pscustomobject]@{ Exists = $true; Record = (ConvertTo-DetachedRecord $obj); Error = '' }
7087: }
