7089: # Replaces the status file atomically (Write-JsonFile: temp + rename; readers never see a
7090: # partial file); `updated` is set here. Throws on failure - the caller decides what it means.
7091: function Write-DetachedStatus {
7092:     param([string]$Path, $Record)
7093:     $Record.updated = Get-IsoTimestamp
7094:     Write-JsonFile -Path $Path -Object $Record
7095: }
