7117: # "45 s" | "12 min" | "2 h 05 min" | "3 d 04 h"
7118: function Format-DetachedSpan {
7119:     param([TimeSpan]$Span)
7120:     if ($Span.TotalSeconds -lt 0) { $Span = [TimeSpan]::Zero }
7121:     if ($Span.TotalSeconds -lt 90) { return "$([int][Math]::Floor($Span.TotalSeconds)) s" }
7122:     if ($Span.TotalMinutes -lt 90) { return "$([int][Math]::Floor($Span.TotalMinutes)) min" }
7123:     if ($Span.TotalHours -lt 48) { return ('{0} h {1:D2} min' -f [int][Math]::Floor($Span.TotalHours), $Span.Minutes) }
7124:     return ('{0} d {1:D2} h' -f [int][Math]::Floor($Span.TotalDays), $Span.Hours)
7125: }
