7127: # The verdict on one detached run (D5, D6, D11): { State; Exit; Text; Finished; Of }
7128: #   done           the run ended: Exit 0 when its exit was 0, else 1
7129: #   running        not done, its background (pid + start time, on this host) is alive: Exit 2
7130: #   elsewhere      not done, its background runs on another host: liveness cannot be checked
7131: #                  from here and is never judged: Exit 2
7132: #   starting       written by the foreground (no pid yet) less than 60 s ago: Exit 2
7133: #   died           not done, and its background is gone: Exit 1 (its recovery records are
7134: #                  judged by the next run of the task as usual)
7135: #   never-started  still `starting` without a pid after 60 s: Exit 1
7136: #   unreadable     the status file cannot be used ($Problem): Exit 1
7137: # Finished / Of: its members that finished / that run (a roster-skipped entry does not run; a
7138: # member the run never started - skipped "not started: ..." - counts as run and finished).
7139: function Get-DetachedJudgement {
7140:     param($Record, [string]$Problem = '', [DateTimeOffset]$Now = [DateTimeOffset]::Now)
7141:     if ($Problem -or $null -eq $Record) {
7142:         $text = $Problem
7143:         if (-not $text) { $text = 'no status record' }
7144:         return [pscustomobject]@{ State = 'unreadable'; Exit = 1; Text = $text; Finished = 0; Of = 0 }
7145:     }
7146:     $members = @($Record.members | Where-Object { $_ })
7147:     $notStarted = { param($m) [string]$m.state -eq 'skipped' -and [string]$m.outcome -match '^not started' }
7148:     $of = @($members | Where-Object { [string]$_.state -ne 'skipped' -or (& $notStarted $_) }).Count
7149:     $finished = @($members | Where-Object { $script:DetachedMemberDone -contains [string]$_.state -or (& $notStarted $_) }).Count
7150:     $started = ConvertTo-WhenOffset $Record.started
7151:     $startedText = $(if ($Record.started) { [string]$Record.started } else { '(unknown)' })
7152:     $state = [string]$Record.state
7153:     if ($state -eq 'done') {
7154:         $code = $Record.exit
7155:         $exitText = $(if ($null -eq $code) { 'unknown' } else { [string]$code })
7156:         $ok = ($null -ne $code -and [int]$code -eq 0)
7157:         return [pscustomobject]@{ State = 'done'; Exit = $(if ($ok) { 0 } else { 1 }); Text = "done, exit $exitText"; Finished = $finished; Of = $of }
7158:     }
7159:     $bgPid = 0
7160:     if ($null -ne $Record.pid) { $bgPid = [int]$Record.pid }
7161:     if ($bgPid -le 0) {
7162:         $age = $(if ($started) { $Now - $started } else { [TimeSpan]::MaxValue })
7163:         if ($age.TotalSeconds -lt $script:DetachedStartGraceSec) {
7164:             return [pscustomobject]@{ State = 'starting'; Exit = 2; Text = "starting - the background has not reported yet (started $(Format-DetachedSpan $age) ago)"; Finished = $finished; Of = $of }
7165:         }
7166:         return [pscustomobject]@{ State = 'never-started'; Exit = 1; Text = "never started - no background process reported within $($script:DetachedStartGraceSec) s of $startedText; nothing was run (its log may say why)"; Finished = $finished; Of = $of }
7167:     }
7168:     $recordHost = [string]$Record.host
7169:     if ($recordHost -and $recordHost -ine [Environment]::MachineName) {
7170:         return [pscustomobject]@{ State = 'elsewhere'; Exit = 2; Text = "running on host $recordHost since $startedText (pid $bgPid) - its liveness cannot be checked from this host"; Finished = $finished; Of = $of }
7171:     }
7172:     if (Test-PidAlive -ProcessId $bgPid -StartTime ([string]$Record.start_time)) {
7173:         $since = $(if ($started) { " ($(Format-DetachedSpan ($Now - $started)))" } else { '' })
7174:         return [pscustomobject]@{ State = 'running'; Exit = 2; Text = "running since $startedText$since, $finished of $of members finished"; Finished = $finished; Of = $of }
7175:     }
7176:     return [pscustomobject]@{ State = 'died'; Exit = 1; Text = "died - its background process (pid $bgPid) is gone without a final status, $finished of $of members finished; its recovery records are judged by the next run of the task as usual"; Finished = $finished; Of = $of }
7177: }
