7205: # The line codex-findings.ps1 -List prints for a detached run of the task that is not done ('' for
7206: # a done one): `detached <id8>: running since <t>, k of N members finished`, or its died,
7207: # starting, never-started or other-host wording (D6), with the command that shows it.
7208: function Format-DetachedListLine {
7209:     param($Run, [string]$Task, [DateTimeOffset]$Now = [DateTimeOffset]::Now)
7210:     $j = Get-DetachedJudgement -Record $Run.Record -Problem ([string]$Run.Error) -Now $Now
7211:     if ($j.State -eq 'done') { return '' }
7212:     return "detached $($Run.Id8): $($j.Text) (codex-consult.ps1 -Task $Task -Status -Id $($Run.Id8))"
7213: }
7214: 
7215: # The SessionStart hook's phrase over every task of the collab root (D6): '' when no detached run
7216: # is running, died or finished in the last $FinishedHours hours; else e.g. "; 1 detached
7217: # consultation running (task t)" or "; detached consultations: 1 running (task t), 1 finished
7218: # (task u)". Status files only; nothing is written.
7219: function Get-DetachedPhrase {
7220:     param([string]$CollabRoot, [DateTimeOffset]$Now = [DateTimeOffset]::Now, [int]$FinishedHours = 24)
7221:     if (-not $CollabRoot -or -not [IO.Directory]::Exists($CollabRoot)) { return '' }
7222:     $tasksOf = @{ running = (New-Object System.Collections.Generic.List[string]); finished = (New-Object System.Collections.Generic.List[string]); died = (New-Object System.Collections.Generic.List[string]) }
7223:     $counts = @{ running = 0; finished = 0; died = 0 }
7224:     foreach ($dir in [IO.Directory]::GetDirectories($CollabRoot)) {
7225:         $task = [IO.Path]::GetFileName($dir)
7226:         foreach ($run in (Read-DetachedRuns -TaskDir $dir)) {
7227:             $j = Get-DetachedJudgement -Record $run.Record -Problem ([string]$run.Error) -Now $Now
7228:             $cat = ''
7229:             if (@('running', 'elsewhere', 'starting') -contains $j.State) { $cat = 'running' }
7230:             elseif (@('died', 'never-started', 'unreadable') -contains $j.State) { $cat = 'died' }
7231:             else {
7232:                 $fin = ConvertTo-WhenOffset $run.Record.finished
7233:                 if ($fin -and ($Now - $fin).TotalHours -lt $FinishedHours) { $cat = 'finished' }
7234:             }
7235:             if (-not $cat) { continue }
7236:             $counts[$cat]++
7237:             if (-not $tasksOf[$cat].Contains($task)) { $tasksOf[$cat].Add($task) }
7238:         }
7239:     }
7240:     $parts = New-Object System.Collections.Generic.List[string]
7241:     foreach ($cat in @('running', 'finished', 'died')) {
7242:         if ($counts[$cat] -eq 0) { continue }
7243:         $tasks = @($tasksOf[$cat])
7244:         $shown = ($tasks | Select-Object -First 3) -join ', '
7245:         if ($tasks.Count -gt 3) { $shown += ', ...' }
7246:         $parts.Add("$cat ($(if ($tasks.Count -eq 1) { 'task' } else { 'tasks' }) $shown)")
7247:     }
7248:     if ($parts.Count -eq 0) { return '' }
7249:     $total = $counts.running + $counts.finished + $counts.died
7250:     if ($parts.Count -eq 1) {
7251:         return "; $total detached consultation$(if ($total -ne 1) { 's' }) $($parts[0])"
7252:     }
7253:     $withCounts = @(foreach ($cat in @('running', 'finished', 'died')) { if ($counts[$cat] -gt 0) { "$($counts[$cat]) " + (@($parts | Where-Object { $_.StartsWith("$cat ") }) | Select-Object -First 1) } })
7254:     return "; detached consultations: $($withCounts -join ', ')"
7255: }
7256: 
7257: # Makes a record final (D3): state done, the exit code, finished and wall_seconds (from `started`)
7258: # unless already set, the summary ($Summary when given, else the one it has, else $Line, else a
7259: # pointer to the log), and every member still pending -> skipped "not started: <the first summary
7260: # line>", still running -> failed "stopped: the run ended (exit <e>) before this member finished".
7261: # Idempotent: the run's own final write and the background's confirmation after it agree.
7262: function Complete-DetachedRecord {
7263:     param($Record, [int]$Exit, [string]$Summary = '', [string]$Line = '')
7264:     $now = Get-Date
7265:     $Record.state = 'done'
7266:     $Record.exit = $Exit
7267:     if (-not $Record.finished) { $Record.finished = Get-IsoTimestamp $now }
7268:     if ($null -eq $Record.wall_seconds) {
7269:         $st = ConvertTo-WhenOffset $Record.started
7270:         if ($st) { $Record.wall_seconds = [math]::Round(([DateTimeOffset]$now - $st).TotalSeconds, 1) }
7271:     }
7272:     if ($Summary) { $Record.summary = $Summary }
7273:     elseif (-not $Record.summary) {
7274:         $Record.summary = $(if ($Line) { $Line } else { "codex-consult: the detached run ended with exit $Exit without a summary; its console output is in $($Record.log)" })
7275:     }
7276:     $why = ConvertTo-OneLine ((([string]$Record.summary) -split "`n")[0] -replace '^codex-consult:\s*', '')
7277:     if ($why.Length -gt 200) { $why = $why.Substring(0, 197) + '...' }
7278:     foreach ($m in @($Record.members | Where-Object { $_ })) {
7279:         if ($m.state -eq 'pending') { $m.state = 'skipped'; $m.outcome = "not started: $why" }
7280:         elseif ($m.state -eq 'running') { $m.state = 'failed'; $m.outcome = "stopped: the run ended (exit $Exit) before this member finished" }
7281:     }
