6140: # Process start time as a UTC round-trip string. $null: no such process. '': the
6141: # process exists but its start time cannot be read (e.g. another user's process).
6142: function Get-ProcessStartIso {
6143:     param([int]$ProcessId)
6144:     $p = $null
6145:     try { $p = Get-Process -Id $ProcessId -ErrorAction Stop } catch { return $null }
6146:     try { return $p.StartTime.ToUniversalTime().ToString('o', $script:Invariant) } catch { return '' }
6147: }
6148: 
6149: # Do two start times (UTC round-trip strings from Get-ProcessStartIso) name the same
6150: # process start? Windows reports a process's start time exactly. .NET on Linux derives
6151: # Process.StartTime from a boot time that every process computes for itself
6152: # (CLOCK_REALTIME_COARSE - CLOCK_BOOTTIME), so two processes reading the SAME pid get
6153: # values a few milliseconds apart. Outside Windows, less than one second apart counts
6154: # as the same start (a pid is not handed out again that fast).
6155: function Test-SameStartTime {
6156:     param([string]$A, [string]$B)
6157:     if ($A -eq $B) { return $true }
6158:     if ($script:OnWindows) { return $false }
6159:     $ta = [DateTimeOffset]::MinValue
6160:     $tb = [DateTimeOffset]::MinValue
6161:     $styles = [System.Globalization.DateTimeStyles]::AssumeUniversal
6162:     if (-not [DateTimeOffset]::TryParse($A, $script:Invariant, $styles, [ref]$ta)) { return $false }
6163:     if (-not [DateTimeOffset]::TryParse($B, $script:Invariant, $styles, [ref]$tb)) { return $false }
6164:     return ([math]::Abs($ta.UtcTicks - $tb.UtcTicks) -lt [TimeSpan]::TicksPerSecond)
6165: }
